#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float2 amzp_position;
uniform float amzp_radius;
uniform float amzp_brightness;
uniform float amzp_shine;
layout(color) uniform half4 amzp_color;
uniform float amzp_pointCount;
uniform float amzp_alpha;
uniform float amzp_blendMode;


        float2 l2s( float2 v ) {
            return (float4(v,0.,1.)*amzLayerToScreen()).xy;
        }

        float circle(float2 st, float2 center, float r) {
            return smoothstep(r,r-.001,length(st-center));
        }

        float smoothCircle(float2 st, float2 center, float r, float innerRad) {
            return smoothstep(r,innerRad,length(st-center));
        }

        float bokeh(float2 st, float2 center, float r, float feather) {
            return smoothstep(r,r*(1.-feather),length(st-center)) - smoothstep(r*(1.-feather),r*(1.-feather*2.),length(st-center)) + smoothstep(r,r*(1.-feather*2.),length(st-center))*1.608;
        }

        float ring(float2 st, float2 center, float r, float feather) {
            float dist = length(st-center);
            return smoothstep(r,r*(1.-feather),length(st-center)) - smoothstep(r*(1.-feather),r*(1.-feather*2.),dist) + smoothstep(0.,r,dist)*0.880*smoothstep(r+feather/2.,r,dist);
        }


        float star(float2 st, float2 center, float r, float insideRadiusScale, float points) {
            float2 dc = st-center;
            float ir = r*insideRadiusScale;
            float a = (atan(dc.x,dc.y)+3.14159)/2.;
            float p = smoothstep(r,ir,length(dc));

            a = smoothstep(p,ir,abs(sin(a*points)));
            return clamp((p*1.264+a)*p*p,0.,1.);
        }

        float combine(float p, float q) {
            return p+q;
        }

        float lensFlare(float2 st, float2 center, float2 offset, float r, float amzp_shine, float points) {
            float2 amzLocal_pos = offset;
            float2 offs = amzLocal_pos-center;
            float2 opp = center-offs;
            float dist = length(amzLocal_pos-center);
            float exposure = (1.-dist)+.5 * amzp_shine;
            exposure = 0.2 + (exposure*0.8);

            float p = 0.;

            p = combine(p,bokeh(st,mix(amzLocal_pos,opp,1.102),0.121*r,0.258)*0.116);

            p = combine(p,bokeh(st,opp,0.092*r,0.268)*0.116);

            p = combine(p,bokeh(st,mix(amzLocal_pos,opp,0.892),0.132*r,0.268)*0.116);

            p = combine(p,bokeh(st,mix(amzLocal_pos,opp,0.740),0.076*r,0.148)*0.116);

            p = combine(p,star(st,mix(amzLocal_pos,opp,0.820),0.164*r,-0.620+exposure*0.1,points)*1.000*exposure);
            p = combine(p,star(st,mix(amzLocal_pos,opp,0.820),0.164*r,-0.620+exposure*0.1,points*2.)*0.440*exposure);

            p = combine(p,bokeh(st,mix(amzLocal_pos,opp,0.428),0.044*r,0.148)*0.116);
            p = combine(p,bokeh(st,mix(amzLocal_pos,opp,0.484),0.028*r,0.268)*0.116);
            p = combine(p,bokeh(st,mix(amzLocal_pos,opp,0.564),0.020*r,0.268)*0.116);

            p = combine(p,bokeh(st,mix(amzLocal_pos,opp,0.276),0.020*r,0.268)*0.116);
            p = combine(p,bokeh(st,mix(amzLocal_pos,opp,0.204),0.076*r,0.228)*0.116);

            p = combine(p,star(st,amzLocal_pos,0.468*r,-0.236+exposure*0.1,points)*5.032*exposure);
            p = combine(p,ring(st,amzLocal_pos+float2(0.000,0.000),0.534*exposure*r,0.052)*0.296);
            p = combine(p,smoothCircle(st,amzLocal_pos,0.12*r,0.05*r)*max(0.2,0.1+exposure));

            return p;
        }

        void amzRender() {
            float4 texColor = amzTexture(0,amzScreenNorm());
            float2 st = amzLayerNorm();
            st.y = 1. - st.y;
            st -= 0.5;
            st.x *= layer.x/layer.y;

            float p = lensFlare(st,float2(0.,0.),amzp_position/1000.0,amzp_radius,amzp_shine*0.995,amzp_pointCount);

            float4 adjColor = clamp(float4(mix(amzp_color.rgb+float3(0.15,0.15,0.15),float3(1.),0.05)*p*amzp_brightness,1.),0.,1.)*p;

            float4 result;
            if( int(amzp_blendMode)==1 ) {
                result = float4((texColor.rgb/texColor.a)*adjColor.rgb,1.0) * texColor.a;
            } else if( int(amzp_blendMode)==2 ) {
                result = float4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-adjColor.rgb)),1.0) * texColor.a;
            } else {
                result = adjColor*texColor.a;
                result = texColor*(1.-result.a) + result;
            }
            amzOutput = mix(texColor,clamp(result,0.,1.),amzp_alpha);
        }


half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

